<script setup>
import { uniqueKey } from '../../services/ids.js';
import { ref,reactive,computed,onMounted } from 'vue';
import { useRouter } from 'vue-router';
import { api } from '../../services/api.js';
import { workspace } from '../../services/workspace.js';
import { canFeature } from '../../services/auth.js';
import { notify } from '../../services/notifications.js';
import { fetchAll,money } from '../../services/panel.js';
import Icon from '../../components/Icon.vue';
const router=useRouter(),products=ref([]),store=ref(null),loading=ref(true),saving=ref(false),error=ref('');
const form=reactive({customer:{name:'',email:'',phone:'',address:'',city:'',postalCode:'',notes:''},items:[{productId:'',variantId:'',quantity:1}],deliveryId:'',paymentId:'',idempotencyKey:uniqueKey()});
const digitalOnly=computed(()=>form.items.length>0&&form.items.every(i=>product(i)?.type==='digital'));
const deliveries=computed(()=>store.value?.deliveries?.filter(d=>d.active&&(digitalOnly.value||d.type!=='digital'))||[]);
const payments=computed(()=>store.value?.payments?.filter(p=>p.active&&(p.type!=='mercadopago'||canFeature('payments.mercadopago'))&&(!p.deliveryIds?.length||p.deliveryIds.includes(form.deliveryId)))||[]);
const delivery=computed(()=>deliveries.value.find(d=>d.id===form.deliveryId));
const subtotal=computed(()=>form.items.reduce((sum,i)=>sum+price(i)*Number(i.quantity||0),0));
function product(i){return products.value.find(p=>p._id===i.productId)}
function price(i){const p=product(i);return Number(p?.variants?.find(v=>v.id===i.variantId)?.price??p?.price??0)}
function choose(i){i.variantId=product(i)?.variants?.[0]?.id||'';form.paymentId='';if(!deliveries.value.some(d=>d.id===form.deliveryId))form.deliveryId=''}
onMounted(async()=>{try{[products.value,store.value]=await Promise.all([fetchAll(`/stores/${workspace.activeStoreId}/products`),api.get(`/stores/${workspace.activeStoreId}`)]);products.value=products.value.filter(p=>p.active)}catch(e){error.value=e.message}finally{loading.value=false}});
async function save(){saving.value=true;error.value='';try{if(form.items.some(i=>!i.productId))throw new Error('Seleccioná un producto en cada fila.');const result=await api.post(`/stores/${workspace.activeStoreId}/orders`,form);const order=result.order||result;notify.success('Pedido creado. El stock quedó reservado.');router.push(`/app/orders/${order._id}`)}catch(e){error.value=e.message;notify.error(e.message)}finally{saving.value=false}}
</script>
<template><div><RouterLink to="/app/orders" class="p-back-link"><Icon name="back" :size="14"/>Volver a pedidos</RouterLink><header class="p-page-header"><div><h1>Nuevo pedido</h1><p>Registrá una venta y reservá el stock con los mismos controles que usa tu tienda.</p></div></header><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><form v-else @submit.prevent="save"><div class="p-two-column"><div><section class="p-section-card"><div class="p-section-title"><h2>Datos del cliente</h2></div><div class="p-form-grid"><div class="p-field"><label for="order-name">Nombre y apellido *</label><input id="order-name" v-model.trim="form.customer.name" required maxlength="120"/></div><div class="p-field"><label for="order-email">Correo electrónico *</label><input id="order-email" v-model.trim="form.customer.email" type="email" required maxlength="254"/></div><div class="p-field"><label for="order-phone">Teléfono *</label><input id="order-phone" v-model.trim="form.customer.phone" type="tel" required maxlength="40"/></div></div></section><section class="p-section-card"><div class="p-section-title"><h2>Productos del pedido</h2><button type="button" class="btn btn-secondary btn-small" @click="form.items.push({productId:'',variantId:'',quantity:1})"><Icon name="plus" :size="14"/>Agregar</button></div><div class="p-table-scroll"><table class="p-table"><thead><tr><th>Producto / variante</th><th>Cantidad</th><th>Subtotal</th><th/></tr></thead><tbody><tr v-for="(item,i) in form.items" :key="i"><td><select v-model="item.productId" class="p-table-input" required :aria-label="`Producto ${i+1}`" @change="choose(item)"><option value="">Seleccionar producto</option><option v-for="p in products" :key="p._id" :value="p._id">{{p.name}} · {{money(p.price)}}</option></select><select v-if="product(item)?.variants?.length" v-model="item.variantId" class="p-table-input" style="margin-top:8px" required :aria-label="`Variante del producto ${i+1}`"><option v-for="v in product(item).variants" :key="v.id" :value="v.id">{{v.name}}</option></select></td><td><input v-model.number="item.quantity" class="p-table-input p-stock-input" type="number" min="1" max="1000" step="1" required :aria-label="`Cantidad del producto ${i+1}`"/></td><td>{{money(price(item)*item.quantity)}}</td><td><button type="button" class="p-icon-btn danger" :disabled="form.items.length<=1" title="Quitar producto" @click="form.items.splice(i,1)"><Icon name="trash" :size="14"/></button></td></tr></tbody></table></div></section><section class="p-section-card"><div class="p-section-title"><h2>Cobro y entrega</h2></div><div class="p-form-grid"><div class="p-field"><label for="order-delivery">Forma de entrega *</label><select id="order-delivery" v-model="form.deliveryId" required @change="form.paymentId=''"><option value="">Seleccionar entrega</option><option v-for="d in deliveries" :key="d.id" :value="d.id">{{d.name}} · {{money(d.price)}}</option></select></div><div class="p-field"><label for="order-payment">Medio de pago *</label><select id="order-payment" v-model="form.paymentId" required :disabled="!form.deliveryId"><option value="">Seleccionar pago</option><option v-for="p in payments" :key="p.id" :value="p.id">{{p.name}}</option></select></div><template v-if="delivery&&['shipping','custom'].includes(delivery.type)"><div class="p-field full"><label for="order-address">Dirección de entrega *</label><input id="order-address" v-model.trim="form.customer.address" required maxlength="300"/></div><div class="p-field"><label for="order-city">Localidad *</label><input id="order-city" v-model.trim="form.customer.city" required maxlength="100"/></div><div class="p-field"><label for="order-postal">Código postal *</label><input id="order-postal" v-model.trim="form.customer.postalCode" required maxlength="20"/></div></template><div class="p-field full"><label for="order-notes">Notas del pedido</label><textarea id="order-notes" v-model="form.customer.notes" rows="3" maxlength="2000"/></div></div><p v-if="!deliveries.length||!store.payments?.some(p=>p.active)" class="p-info p-warning">Primero configurá las formas de <RouterLink to="/app/payments">cobro y entrega</RouterLink>.</p></section></div><aside class="p-order-summary"><h3>Resumen</h3><div class="p-summary-line"><span>Productos</span><strong>{{money(subtotal)}}</strong></div><div class="p-summary-line"><span>Entrega</span><strong>{{money(delivery?.price)}}</strong></div><div class="p-summary-line total"><span>Total</span><strong>{{money(subtotal+Number(delivery?.price||0))}}</strong></div><p class="p-help">El total definitivo se calcula y valida al crear el pedido.</p><div class="p-info">Crear un pedido no confirma el pago. Podés verificarlo después desde el detalle.</div><button class="btn btn-primary" style="width:100%" :disabled="saving||!form.paymentId">{{saving?'Creando pedido...':'Crear pedido'}}</button></aside></div></form></div></template>
